insert into clients (id, name, goal, notes) values ('3bea883a-9020-5c93-9cf2-9c4fdfcc70a8', '🩹 Injury Prevention Templates', 'Program templates', 'Five 6-week prehab programs — shoulder, lower back, knee, ankle, hip. Prehab, not rehab: for building resilience, not treating an active injury. Duplicate to a real client, then adjust. Run each week''s session 2-3x/week (20-35 min). Rest: 30-60s mobility/activation, 60-90s strength.') on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('b08da054-7485-5be6-aed1-c1c769aa5f0a', '3bea883a-9020-5c93-9cf2-9c4fdfcc70a8', 'Shoulder Injury Prevention (6wk)', 'Functional', 'Beginner', 6, '{"1": "Rotator cuff endurance, scapular control, T-spine mobility, overhead positioning. For lifters, throwers, swimmers, and repetitive reachers/pressers. Learn technique — slow tempo, easy range of motion, no added load. Warm up 5–10 min first (light cardio + dynamic mobility). Pain rule: mild effort or muscle fatigue is OK; sharp pain, numbness/tingling, or >5/10 means stop and modify.", "2": "Build consistency — add reps only if form is clean.", "3": "Add resistance — bands, light DBs, or longer holds. Progress only when movement stays controlled, balanced, and pain-free.", "4": "Increase control demands — slower eccentrics, single-leg work, balance reaches.", "5": "Athletic integration — low-level hops, carries, deceleration, compound movement.", "6": "Rehearse performance quality — keep reps crisp; do not chase fatigue at the expense of mechanics. After week 6: keep the 4–6 most helpful drills, 2 days/week, to maintain."}'::jsonb) on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('7d8d30e3-5479-5835-b297-164ef1fda56f', '3bea883a-9020-5c93-9cf2-9c4fdfcc70a8', 'Lower Back Injury Prevention (6wk)', 'Functional', 'Beginner', 6, '{"1": "Trunk endurance, hip mobility, glute strength, safe bend-and-brace mechanics. Spine control over max strength. Learn technique — slow tempo, easy range of motion, no added load. Warm up 5–10 min first (light cardio + dynamic mobility). Pain rule: mild effort or muscle fatigue is OK; sharp pain, numbness/tingling, or >5/10 means stop and modify.", "2": "Build consistency — add reps only if form is clean.", "3": "Add resistance — bands, light DBs, or longer holds. Progress only when movement stays controlled, balanced, and pain-free.", "4": "Increase control demands — slower eccentrics, single-leg work, balance reaches.", "5": "Athletic integration — low-level hops, carries, deceleration, compound movement.", "6": "Rehearse performance quality — keep reps crisp; do not chase fatigue at the expense of mechanics. After week 6: keep the 4–6 most helpful drills, 2 days/week, to maintain."}'::jsonb) on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('e0c4f235-9ef3-59b1-bf7d-24f3bce7cffa', '3bea883a-9020-5c93-9cf2-9c4fdfcc70a8', 'Knee Injury Prevention (6wk)', 'Functional', 'Beginner', 6, '{"1": "Hip-knee-ankle alignment, single-leg control, landing mechanics, quad/ham strength, deceleration. Knee tracks over the middle toes on everything. Learn technique — slow tempo, easy range of motion, no added load. Warm up 5–10 min first (light cardio + dynamic mobility). Pain rule: mild effort or muscle fatigue is OK; sharp pain, numbness/tingling, or >5/10 means stop and modify.", "2": "Build consistency — add reps only if form is clean.", "3": "Add resistance — bands, light DBs, or longer holds. Progress only when movement stays controlled, balanced, and pain-free.", "4": "Increase control demands — slower eccentrics, single-leg work, balance reaches.", "5": "Athletic integration — low-level hops, carries, deceleration, compound movement.", "6": "Rehearse performance quality — keep reps crisp; do not chase fatigue at the expense of mechanics. After week 6: keep the 4–6 most helpful drills, 2 days/week, to maintain."}'::jsonb) on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('38ee80ac-0cec-563d-b843-9620ff789117', '3bea883a-9020-5c93-9cf2-9c4fdfcc70a8', 'Ankle Injury Prevention (6wk)', 'Functional', 'Beginner', 6, '{"1": "Ankle mobility, calf/foot strength, balance, proprioception, cutting/landing control. Built for court, field, running, and jumping sports. Learn technique — slow tempo, easy range of motion, no added load. Warm up 5–10 min first (light cardio + dynamic mobility). Pain rule: mild effort or muscle fatigue is OK; sharp pain, numbness/tingling, or >5/10 means stop and modify.", "2": "Build consistency — add reps only if form is clean.", "3": "Add resistance — bands, light DBs, or longer holds. Progress only when movement stays controlled, balanced, and pain-free.", "4": "Increase control demands — slower eccentrics, single-leg work, balance reaches.", "5": "Athletic integration — low-level hops, carries, deceleration, compound movement.", "6": "Rehearse performance quality — keep reps crisp; do not chase fatigue at the expense of mechanics. After week 6: keep the 4–6 most helpful drills, 2 days/week, to maintain."}'::jsonb) on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('8f29a1c9-b520-5ff1-b3d3-56bd58090b27', '3bea883a-9020-5c93-9cf2-9c4fdfcc70a8', 'Hip Injury Prevention (6wk)', 'Functional', 'Beginner', 6, '{"1": "Hip mobility, glute strength, pelvic control, lateral stability, single-leg mechanics. Strong hips protect the low back, knees, and ankles. Learn technique — slow tempo, easy range of motion, no added load. Warm up 5–10 min first (light cardio + dynamic mobility). Pain rule: mild effort or muscle fatigue is OK; sharp pain, numbness/tingling, or >5/10 means stop and modify.", "2": "Build consistency — add reps only if form is clean.", "3": "Add resistance — bands, light DBs, or longer holds. Progress only when movement stays controlled, balanced, and pain-free.", "4": "Increase control demands — slower eccentrics, single-leg work, balance reaches.", "5": "Athletic integration — low-level hops, carries, deceleration, compound movement.", "6": "Rehearse performance quality — keep reps crisp; do not chase fatigue at the expense of mechanics. After week 6: keep the 4–6 most helpful drills, 2 days/week, to maintain."}'::jsonb) on conflict (id) do nothing;
